'use strict';
// Reliability layer. Loaded after the UI modules; initialization happens once here.
const ENGINE_VERSION = '2026.10.04';
let lastStoredRaw=null, storageConflict=false;
const baseCheckedQuestion=checkedQuestion,baseCheckedExam=checkedExam,baseValidateBackup=validateBackup;
checkedQuestion=function(q){const out=baseCheckedQuestion(q);if(Number.isInteger(q.review?.batch)&&q.review.batch>0)out.review={batch:q.review.batch,date:String(q.review.date||''),scope:String(q.review.scope||''),status:'editorial'};return out};
checkedExam=function(e,active=false){const out=baseCheckedExam(e,active);out.strict=e.strict!==false;out.bankScope=e.bankScope==='all'?'all':'reviewed';out.timerModel=e.timerModel===2?2:1;out.unobservedSeconds=Number.isFinite(e.unobservedSeconds)&&e.unobservedSeconds>=0?e.unobservedSeconds:0;if(e.profile==='sectioned'){const count=e.blockCount??6,size=e.blockSize??20,minutes=e.blockMinutes??25;if(!Number.isInteger(count)||count<1||count>6||!Number.isInteger(size)||size<1||size>100||count*size!==out.qs.length||!Number.isFinite(minutes)||minutes<1||minutes>90||!Number.isInteger(e.block)||e.block<0||e.block>=count||!Number.isFinite(e.blockDeadline)||e.blockDeadline<e.startedAt||e.blockDeadline>e.deadline||out.index<e.block*size||out.index>=(e.block+1)*size)throw Error('إعداد الأقسام في النسخة الاحتياطية غير صالح.');Object.assign(out,{blockCount:count,blockSize:size,blockMinutes:minutes,block:e.block,blockDeadline:e.blockDeadline})}if(active){out.lastTouch=Number.isFinite(e.lastTouch)?Math.max(e.startedAt,Math.min(e.lastTouch,e.deadline)):Math.min(Date.now(),e.deadline);out.clockSuspended=true}return out};
validateBackup=function(s){const out=baseValidateBackup(s);out.history=out.history.map((h,i)=>{const source=s.history[i];if(!Number.isFinite(Date.parse(h.at)))throw Error('تاريخ غير صالح في سجل المحاولات.');return {...h,...(typeof source.contentKey==='string'?{contentKey:source.contentKey}:{}),...(['blank','wrong','correct'].includes(source.status)?{status:source.status}:{})}});Object.assign(out.settings,{bankScope:s.settings?.bankScope==='all'?'all':'reviewed',strict:s.settings?.strict!==false,simBlocks:[3,4,5,6].includes(s.settings?.simBlocks)?s.settings.simBlocks:5,simSize:[10,20,24,30].includes(s.settings?.simSize)?s.settings.simSize:24,simMinutes:[10,15,20,25,30].includes(s.settings?.simMinutes)?s.settings.simMinutes:25,simVerbal:[50,55,75].includes(s.settings?.simVerbal)?s.settings.simVerbal:50,...(Number.isFinite(Date.parse(s.settings?.backupAt))?{backupAt:s.settings.backupAt}:{})});return out};
function contentKey(q){return JSON.stringify([q.text.trim(),[...q.options].sort(),q.options[q.answer],q.category,q.section])}
function isReviewed(q){return Number.isInteger(q.review?.batch)&&q.review.batch>0}
function questionBank(){return settings.bankScope==='all'?data.questions:data.questions.filter(isReviewed)}
stats=function(){const h=learningHistory(),correct=h.filter(h=>h.correct).length;return `<div class="stats"><div class="stat"><span>أسئلة ضمن البنك المختار</span><strong>${num(questionBank().length)}</strong></div><div class="stat"><span>محاولات تشمل المتروك</span><strong>${num(h.length)}</strong></div><div class="stat"><span>صحيح من كل المحاولات</span><strong>${h.length?num(Math.round(correct/h.length*100))+'٪':'—'}</strong></div></div>`};
const basePracticeUI=practice;
practice=function(){basePracticeUI();const filter=document.createElement('label');filter.innerHTML=`بنك الأسئلة<select id="practice-scope"><option value="reviewed">المراجع تحريريًا فقط</option><option value="all">البنك الكامل مع الإضافات</option></select>`;$('#main .filters')?.appendChild(filter);$('#practice-scope').value=settings.bankScope==='all'?'all':'reviewed';$('#practice-scope').onchange=e=>{settings.bankScope=e.target.value;question=null;save();practice()}};
function blockSize(e=exam){return e?.blockSize||20}
function blockCount(e=exam){return e?.blockCount||6}
function blockMs(e=exam){return (e?.blockMinutes||25)*60000}
function locked(){return !!exam&&exam.strict!==false}
startExam=function(name,mode='fixed'){if(exam){go('exams');return}if(mode==='random'){startLearningExam('standard');return}if(mode!=='fixed'||!Object.hasOwn(data.tests,name))throw Error('اختبار غير موجود');const qs=data.tests[name].map(id=>data.questions.find(q=>q.id===id));if(qs.some(q=>!q))throw Error('تعذّر إيجاد بعض أسئلة النموذج');if(settings.bankScope!=='all'&&qs.some(q=>!isReviewed(q))){alert('يحتوي النموذج على سؤال معدّل محليًا وغير مراجع. اختر البنك الكامل صراحة أو استخدم اختبارًا متجددًا من البنك المراجع.');return}const now=Date.now();exam={id:uid(),name,mode,qs:clone(qs),answers:Array(qs.length).fill(null),times:Array(qs.length).fill(0),flags:Array(qs.length).fill(false),index:0,startedAt:now,deadline:now+75*60000,lastTouch:now,strict:settings.strict!==false,bankScope:settings.bankScope==='all'?'all':'reviewed',timerModel:2,unobservedSeconds:0};save();activate('exams');renderExam();runTimer()};
function syncNavigation(){document.querySelectorAll('[data-view]').forEach(b=>{b.disabled=locked()&&b.dataset.view!=='exams';b.title=b.disabled?'أنهِ المحاكاة الصارمة أولًا أو نزّل نسخة احتياطية من شاشة الاختبار.':''})}
function exportBackup(){touchExam();settings.backupAt=new Date().toISOString();save();downloadBlob('GAT_Backup_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(snapshot(),null,2),'application/json')}
go=function(v){if(locked()&&v!=='exams'){alert('المحاكاة الصارمة تمنع فتح الدروس والحلول أثناء الاختبار. أنهِ المحاولة أولًا؛ ويمكنك تنزيل نسخة احتياطية من شاشة الاختبار.');return}if(exam){touchExam();save()}activate(v);render();syncNavigation();$('#main')?.focus?.()};
save=function(){try{const current=localStorage.getItem(STORE);if(storageConflict||current!==lastStoredRaw){storageConflict=true;warning('تغيّرت البيانات في نافذة أخرى. أوقف العمل هنا، ونزّل نسخة احتياطية من بيانات هذه النافذة عند الحاجة، ثم أعد تحميلها. لن تُكتب بيانات فوق التحديث الآخر.');return false}const raw=JSON.stringify(snapshot());localStorage.setItem(STORE,raw);lastStoredRaw=raw;localStorage.removeItem('gat-progress-v1');warning('');return true}catch{warning('لم تُحفظ آخر التغييرات في المتصفح. نزّل نسخة احتياطية قبل إغلاق الصفحة.');return false}};
record=function(q,a){if(!answered(a))return;history.push({id:q.id,category:q.category,section:q.section,contentKey:contentKey(q),chosen:a,correct:a===q.answer,status:a===q.answer?'correct':'wrong',at:new Date().toISOString()});save()};
// Merge legacy exam omissions into analytics without altering old report snapshots.
function learningHistory(){const events=history.map(h=>({...h})),seen=new Set(events.filter(h=>h.examId).map(h=>h.examId+'|'+h.id));const versions=new Map();for(const e of attempts)for(let i=0;i<e.qs.length;i++){const q=e.qs[i],key=e.id+'|'+q.id;versions.set(key,contentKey(q));if(!seen.has(key)){events.push({id:q.id,category:q.category,section:q.section,contentKey:contentKey(q),chosen:answered(e.answers[i])?e.answers[i]:null,correct:e.answers[i]===q.answer,status:answered(e.answers[i])?(e.answers[i]===q.answer?'correct':'wrong'):'blank',at:new Date(e.finishedAt).toISOString(),examId:e.id});seen.add(key)}}for(const h of events)if(!h.contentKey&&h.examId)h.contentKey=versions.get(h.examId+'|'+h.id);return events.sort((a,b)=>Date.parse(a.at)-Date.parse(b.at))}
skillStats=function(){const current=new Map(data.questions.map(q=>[q.id,q])),groups=new Map();for(const q of data.questions)if(!groups.has(q.category))groups.set(q.category,{name:q.category,section:q.section,n:0,c:0,ids:new Set(),first:new Map(),repeatN:0,repeatC:0,legacy:0});for(const h of learningHistory()){const q=current.get(h.id),g=q&&groups.get(q.category);if(!g)continue;if(h.contentKey!==contentKey(q)){g.legacy++;continue}g.n++;g.c+=Number(h.correct);g.ids.add(h.id);if(!g.first.has(h.id))g.first.set(h.id,h);else{g.repeatN++;g.repeatC+=Number(h.correct)}}return [...groups.values()].map(g=>({...g,percent:g.first.size?Math.round([...g.first.values()].filter(h=>h.correct).length/g.first.size*100):null,repeatPercent:g.repeatN?Math.round(g.repeatC/g.repeatN*100):null})).sort((a,b)=>(a.percent??-1)-(b.percent??-1))};
reviewItems=function(now=Date.now()){const grouped=new Map();for(const h of learningHistory()){if(!grouped.has(h.id))grouped.set(h.id,[]);grouped.get(h.id).push(h)}return questionBank().flatMap(q=>{const h=(grouped.get(q.id)||[]).filter(h=>h.contentKey===contentKey(q)||(!h.contentKey&&!h.correct));if(!h.some(x=>!x.correct))return [];let streak=0;for(let i=h.length-1;i>=0&&h[i].correct;i--)streak++;const days=[0,1,3,7,14][Math.min(streak,4)],due=Date.parse(h.at(-1).at)+days*86400000;return [{q,streak,due,dueNow:due<=now,blank:h.at(-1).status==='blank'}]})};
progress=function(){const groups=skillStats();$('#main').innerHTML=title('تقدّمك على أسئلة مختلفة','نقيس الإجابة الأولى لكل سؤال بصيغته الحالية، ونفصل عنها نتائج الإعادة.')+stats()+`<section class="card"><h2>مؤشر المهارات</h2><p>يلزم خمسة أسئلة مختلفة على الأقل لاقتراح أولوية تدريب. المتروك يدخل في القياس؛ النتائج القديمة لسؤال تغيّر تبقى في التقارير ولا تُنسب إلى نسخته الجديدة.</p><div class="table-wrap"><table><thead><tr><th>المهارة</th><th>أسئلة مختلفة</th><th>دقة المحاولة الأولى</th><th>محاولات الإعادة</th><th>دقة الإعادة</th><th>الأولوية</th></tr></thead><tbody>${groups.map(g=>`<tr><th>${esc(g.name)}</th><td>${num(g.ids.size)}</td><td>${g.percent===null?'—':num(g.percent)+'٪'}</td><td>${num(g.repeatN)}</td><td>${g.repeatPercent===null?'—':num(g.repeatPercent)+'٪'}</td><td>${g.ids.size<5?'عينة غير كافية':g.percent<70?'تحتاج تدريبًا':'واصل التثبيت'} <button data-focus="${esc(g.name)}">تدرّب</button></td></tr>`).join('')}</tbody></table></div><p class="muted">هذا مؤشر تدريبي لا درجة قياس متوقعة. لا تدخل السجلات القديمة مجهولة صيغة السؤال في دقة المحاولة الأولى.</p></section>`;document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>trainSkill(b.dataset.focus))};
// Only observed, foreground intervals of at most 5 seconds accrue to a question.
// All other wall time is explicit unobserved time; the exam deadline never pauses.
touchExam=function(now=Date.now()){if(!exam)return;const e=exam,end=Math.min(now,e.deadline),previous=Math.min(e.deadline,Math.max(e.startedAt,Number.isFinite(e.lastTouch)?e.lastTouch:e.startedAt));if(end<=previous)return;const delta=end-previous,visible=view==='exams'&&!document.hidden&&!e.clockSuspended;const questionEnd=e.profile==='sectioned'?Math.min(end,e.blockDeadline):end;const active=visible&&delta<=5000?Math.max(0,questionEnd-previous):0;e.times[e.index]+=active/1000;e.unobservedSeconds=(e.unobservedSeconds||0)+(delta-active)/1000;e.lastTouch=end};
syncBlocks=function(){if(!exam)return;touchExam();if(exam.profile==='sectioned'){while(exam&&Date.now()>=exam.blockDeadline){if(exam.block>=blockCount()-1){finishExam('timeout');return}exam.block++;exam.index=exam.block*blockSize();exam.blockDeadline=Math.min(exam.deadline,exam.blockDeadline+blockMs());save()}}if(exam&&Date.now()>=exam.deadline)finishExam('timeout')};
remaining=function(){if(!exam)return '0:00';const seconds=Math.max(0,Math.ceil((Math.min(exam.deadline,exam.profile==='sectioned'?exam.blockDeadline:exam.deadline)-Date.now())/1000));return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`};
jump=function(index){const oldBlock=exam?.block;syncBlocks();if(!exam)return;if(oldBlock!==exam.block){renderExam();return}if(!Number.isInteger(index)||index<0||index>=exam.qs.length)return;if(exam.profile==='sectioned'&&(index<exam.block*blockSize()||index>=(exam.block+1)*blockSize()))return;touchExam();exam.index=index;save();renderExam()};
setExamAnswer=function(value){const id=exam?.id,index=exam?.index;syncBlocks();if(!exam||id!==exam.id||index!==exam.index){if(exam)renderExam();return}if(!answered(value))throw Error('إجابة غير صالحة');touchExam();exam.answers[index]=value;save();renderExam()};
function advanceBlock(){const id=exam?.id,b=exam?.block;syncBlocks();if(!exam||id!==exam.id||b!==exam.block){if(exam)renderExam();return}if(!confirm('سيُغلق القسم الحالي ولن تستطيع العودة إليه. هل تريد المتابعة؟'))return;syncBlocks();if(!exam||id!==exam.id||b!==exam.block){if(exam)renderExam();return}if(exam.block===blockCount()-1){finishExam();return}touchExam();exam.block++;exam.index=exam.block*blockSize();exam.blockDeadline=Date.now()+blockMs();exam.deadline=exam.blockDeadline+(blockCount()-1-exam.block)*blockMs();exam.lastTouch=Date.now();save();renderExam()}
renderExam=function(){syncBlocks();if(!exam)return;originalRenderExam();const e=exam;e.clockSuspended=!!document.hidden;const bar=document.createElement('div');bar.className='study-strip';bar.innerHTML=`<span>${e.strict!==false?'محاكاة صارمة · الدروس والحلول مغلقة حتى التسليم':'تدريب مفتوح · يسمح بالتنقل إلى الدروس'}</span><button id="exam-backup">تنزيل نسخة احتياطية</button>`;$('#main .card').prepend(bar);$('#exam-backup').onclick=exportBackup;if(e.profile==='sectioned'){const start=e.block*blockSize(),end=start+blockSize();$('#prev').disabled=e.index===start;$('#next').disabled=e.index===end-1;document.querySelectorAll('[data-jump]').forEach(b=>{if(+b.dataset.jump<start||+b.dataset.jump>=end)b.remove()});const sectionBar=document.createElement('div');sectionBar.className='study-strip';sectionBar.innerHTML=`<b>القسم ${num(e.block+1)} من ${num(blockCount())} · ${num(blockSize())} سؤالًا · ${num(e.blockMinutes||25)} دقيقة</b><button id="next-block">${e.block===blockCount()-1?'إنهاء الاختبار':'إغلاق القسم والانتقال للتالي'}</button>`;$('#main .card').prepend(sectionBar);$('#next-block').onclick=advanceBlock}const id=e.id,index=e.index;$('#flag').onchange=ev=>{syncBlocks();if(exam?.id===id&&exam.index===index){exam.flags[index]=ev.target.checked;save()}else if(exam)renderExam()};syncNavigation()};
runTimer=function(){clearInterval(timer);timer=setInterval(()=>{if(!exam)return;const b=exam.block;syncBlocks();if(!exam)return;if(b!==exam.block&&view==='exams')renderExam();if($('#time'))$('#time').textContent=remaining();if(Math.floor(Date.now()/1000)%10===0)save()},1000)};
finishExam=function(reason='submitted'){if(!exam)return;touchExam();clearInterval(timer);const e=exam;if(Date.now()>=e.deadline)reason='timeout';e.finishedAt=Math.max(e.startedAt,Math.min(Math.max(Date.now(),e.lastTouch||e.startedAt),e.deadline));e.reason=reason;delete e.lastTouch;delete e.clockSuspended;attempts.push(clone(e));e.qs.forEach((q,i)=>history.push({id:q.id,category:q.category,section:q.section,contentKey:contentKey(q),chosen:answered(e.answers[i])?e.answers[i]:null,correct:q.answer===e.answers[i],status:answered(e.answers[i])?(q.answer===e.answers[i]?'correct':'wrong'):'blank',at:new Date(e.finishedAt).toISOString(),examId:e.id}));exam=null;save();syncNavigation();activate('reports');reviewFilter='all';showReport(e.id)};
const baseReportSummary=reportSummary;
reportSummary=function(e){return baseReportSummary(e)+`<p class="muted">${e.strict===false?'تدريب مفتوح':'محاكاة صارمة أو محاولة قديمة'} · ${e.bankScope==='all'?'شمل البنك الكامل':'بنك مراجع أو نموذج محفوظ'}</p><p>زمن عرض الأسئلة المسجّل: ${duration(e.times.reduce((a,b)=>a+b,0))} · ${e.timerModel===2?'وقت الانقطاع أو عدم رصد العرض: '+duration(e.unobservedSeconds||0):'سجل قديم: قد يشمل زمن السؤال فترات خمول، ولا يمكن تصحيحه بأثر رجعي.'}</p>`};
const baseManage=manage;
manage=function(){baseManage();$('#backup').onclick=exportBackup;const note=document.createElement('section');note.className='card spaced';note.innerHTML=`<h2>نقل البيانات وحمايتها</h2><p>آخر تصدير مسجّل: ${settings.backupAt?new Date(settings.backupAt).toLocaleString('ar-SA'):'لم تُصدّر نسخة بعد'}. احفظ نسخة بعد كل جلسة مهمة وقبل مسح المتصفح أو الانتقال إلى جهاز آخر.</p><p>النتائج خاصة بهذا المتصفح؛ لا توجد مزامنة تلقائية بين الأجهزة. لنقلها: صدّر JSON هنا، ثم استورده من إدارة البيانات على الجهاز الآخر. الاستعادة تستبدل بيانات الجهاز المستهدف ولا تدمجها.</p><p>الأسئلة المستوردة متاحة في التدريب عند اختيار البنك الكامل. لا تحصل تلقائيًا على علامة المراجعة التحريرية ولا تدخل المحاكاة الافتراضية قبل مراجعتها.</p><a href="PROJECT_GUIDE.html" target="_blank" rel="noopener">دليل المشروع والتشغيل الكامل</a>`;$('#main').prepend(note)};
const originalApplyImport=applyImport;
